export const description = `
Execution tests that read no input, found by mutation testing Mesa.

Each case is a compute shader generated by the WGSL fuzzer WGSLsmith and then reduced
automatically. They were found by mutation testing a shader compiler: each program produces
different output when a specific change is injected into the compiler, and no existing CTS test
detected that change.

Each shader writes its result to a storage buffer at @group(0) @binding(1).
Expected output is given as bytes, in the form the fuzzer reports it, with a comment showing the
values of each struct member.

Case names are "shader_" followed by the first 8 hex digits of the SHA-256 hash of the
shader text. kTestData holds each case's shader, its expected output, and the location of the
mutation it detects.
`;

import { makeTestGroup } from '../../../../../common/framework/test_group.js';
import { keysOf } from '../../../../../common/util/data_tables.js';
import { AllFeaturesMaxLimitsGPUTest, GPUTest } from '../../../../gpu_test.js';
import { MutationInfo } from '../mutation_info.js';

export const g = makeTestGroup(AllFeaturesMaxLimitsGPUTest);

interface TestData {
  /** Where the mutation this test detects was made. */
  mutation: MutationInfo;
  /** The shader. */
  code: string;
  /** The expected bytes of the output buffer. */
  expectedOutput: number[];
}

/**
 * Runs a shader (entry point `main`, one invocation) and checks the contents of its output
 * buffer.
 *
 * @param t The test object
 * @param expectedOutput The expected bytes of the storage buffer at @group(0) @binding(1).
 * The buffer starts zero-filled, so padding bytes are expected to be 0.
 * @param wgsl The shader
 */
function runGeneratedTest(t: GPUTest, expectedOutput: Uint8Array, wgsl: string) {
  const pipeline = t.device.createComputePipeline({
    layout: 'auto',
    compute: {
      module: t.device.createShaderModule({ code: wgsl }),
      entryPoint: 'main',
    },
  });

  // New buffers are zero-filled.
  const outputBuffer = t.createBufferTracked({
    size: expectedOutput.byteLength,
    usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_SRC,
  });
  const bindGroup = t.device.createBindGroup({
    layout: pipeline.getBindGroupLayout(0),
    entries: [{ binding: 1, resource: { buffer: outputBuffer } }],
  });

  // Run the shader.
  const encoder = t.device.createCommandEncoder();
  const pass = encoder.beginComputePass();
  pass.setPipeline(pipeline);
  pass.setBindGroup(0, bindGroup);
  pass.dispatchWorkgroups(1);
  pass.end();
  t.queue.submit([encoder.finish()]);

  t.expectGPUBufferValuesEqual(outputBuffer, expectedOutput);
}

const kTestData: Record<string, TestData> = {
  shader_101299f4: {
    mutation: {
      mutant: {
        component: 'mesa',
        version: 'ba8eaab4f07e33c0b74fa92c60852cba2518bf2e',
        file: 'src/compiler/nir/nir_constant_expressions.c',
        line: 48527,
        generatedFrom: 'src/compiler/nir/nir_constant_expressions.py',
      },
      environment: [{ component: 'dawn', version: '9de0fd67086127228e8aa28e69616da37220cfc3' }],
    },
    code: `
struct StorageBuffer {
    a: vec2<i32>,
}

@group(0) @binding(1) var<storage, read_write> s_output: StorageBuffer;

var<private> v: array<i32, 7>;

@compute
@workgroup_size(1i)
fn main() {
    s_output = StorageBuffer(max(vec3<i32>(), vec3<i32>(v[select(abs(5i) % 7i, 0i, 5i == i32(-2147483648))])).xy);
}
`,
    expectedOutput: [0, 0, 0, 0, 0, 0, 0, 0], // s_output: a = (0, 0)
  },
  shader_10c2ef9c: {
    mutation: {
      mutant: {
        component: 'mesa',
        version: 'ba8eaab4f07e33c0b74fa92c60852cba2518bf2e',
        file: 'src/compiler/nir/nir_constant_expressions.c',
        line: 50895,
        generatedFrom: 'src/compiler/nir/nir_constant_expressions.py',
      },
      environment: [{ component: 'dawn', version: '9de0fd67086127228e8aa28e69616da37220cfc3' }],
    },
    code: `
struct StorageBuffer {
    c: i32,
}

@group(0) @binding(1) var<storage, read_write> s_output: StorageBuffer;

var<private> v: array<i32, 5> = array<i32, 5>(1i, 8i, 4i, 8i, 0i);

@compute
@workgroup_size(1i)
fn main(@builtin(local_invocation_id) builtin_local_invocation_id: vec3<u32>) {
    s_output = StorageBuffer(v[countTrailingZeros(vec2<u32>(builtin_local_invocation_id.x, 6u)).x % 5u]);
}
`,
    expectedOutput: [4, 0, 0, 0], // s_output: c = 4
  },
};

g.test('no_input')
  .desc(`Tests compute shaders that read no input, found by mutation testing Mesa.`)
  .params(u => u.combine('case', keysOf(kTestData)))
  .fn(t => {
    const c = kTestData[t.params.case];
    runGeneratedTest(t, new Uint8Array(c.expectedOutput), c.code);
  });
